import unittest
import api

class IndependentBehavior(unittest.TestCase):
    def test_tail(self): self.assertEqual(api.partition([0,1,2,3,4,5,6],3),[[0,1,2],[3,4,5],[6]])
    def test_short(self): self.assertEqual(api.partition([7],4),[[7]])
    def test_empty(self): self.assertEqual(api.partition([],3),[])
    def test_unit(self): self.assertEqual(api.partition([5,6],1),[[5],[6]])
    def test_invalid(self):
        with self.assertRaises(ValueError): api.partition([1,2],-1)
    def test_helper(self): self.assertEqual(api.flatten([[1],[],[2,3]]),[1,2,3])
